Este seu esquema de esconder os options por classes não me parece uma boa ideia.
Como não sei exatamente o que você está fazendo não tenho como propor uma solução melhor.
Segue abaixo o código que funciona da forma como você descreveu:

  $(document).ready(function() {
     $('#instituicao_tur').change(function() {
         $('option[class^="id_cur"]').hide();
         
         var val = $(this).val();
          if (val == 0) {
              $('.curso_zero').hide();
          } else {
              $('.id_cur'+val).show();
          }
      });
      
     $('#curso_tur').change(function() {
         $('option[class^="id_polo"]').hide();
         $('.id_polo'+$(this).val()).show();
      });  
});
